test("キーの並びが違っても、同じキーに同じ値を持つオブジェクトは等しい", () => {
  expect(Json.equals({ a: 1, b: "x" }, { b: "x", a: 1 })).toBe(true);
});

test("入れ子の値まで同じなら等しい", () => {
  expect(
    Json.equals({ list: [1, { c: true }] }, { list: [1, { c: true }] }),
  ).toBe(true);
});

test("配列の並びが違えば等しくない", () => {
  expect(Json.equals([1, 2], [2, 1])).toBe(false);
});

test("後ろの値にしか無いキーがあれば等しくない", () => {
  expect(Json.equals({ a: 1 }, { a: 1, b: 2 })).toBe(false);
});

test("前の値にしか無いキーがあれば等しくない", () => {
  expect(Json.equals({ a: 1, b: 2 }, { a: 1 })).toBe(false);
});

test("入れ子の値が違えば等しくない", () => {
  expect(Json.equals({ a: { b: 1 } }, { a: { b: 2 } })).toBe(false);
});

test("空の配列と空のオブジェクトは等しくない", () => {
  expect(Json.equals([], {})).toBe(false);
});

test("空のオブジェクトと空の配列は等しくない", () => {
  expect(Json.equals({}, [])).toBe(false);
});

test("キーの数が同じでも、前の値だけが自身のキーとして __proto__ を持つなら等しくない", () => {
  const ownProto: JsonValue = JSON.parse('{"__proto__":{}}');

  expect(Json.equals(ownProto, { x: {} })).toBe(false);
});

test("文字列の数字と数値は等しくない", () => {
  expect(Json.equals("1", 1)).toBe(false);
});

test("渡した比べ方で同じ位置の要素がすべて等しければ、並びは等しい", () => {
  const sameId = (a: { id: number }, b: { id: number }) => a.id === b.id;

  expect(ArrayEx.equals([{ id: 1 }], [{ id: 1 }], sameId)).toBe(true);
});

test("渡した比べ方で等しくない位置が 1 つでもあれば、並びは等しくない", () => {
  const sameId = (a: { id: number }, b: { id: number }) => a.id === b.id;

  expect(
    ArrayEx.equals([{ id: 1 }, { id: 2 }], [{ id: 1 }, { id: 3 }], sameId),
  ).toBe(false);
});

test("渡した比べ方がどの要素も等しいとみなしても、長さが違う並びは等しくない", () => {
  expect(ArrayEx.equals([1], [1, 2], () => true)).toBe(false);
});

test("別々に作った同じ中身のドキュメントは同じとみなす", () => {
  expect(
    DesignDocument.isSameContent(
      documentWithPrimary("#000000"),
      documentWithPrimary("#000000"),
    ),
  ).toBe(true);
});

test("トークンの値が 1 つ違えば同じとみなさない", () => {
  expect(
    DesignDocument.isSameContent(
      documentWithPrimary("#000000"),
      documentWithPrimary("#ffffff"),
    ),
  ).toBe(false);
});

test("中身の変わらない編集を積んでも、1 回戻れば直前の編集の前へ戻る", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );

  const unchanged = EditHistory.record(edited, documentOfWidth(414));

  const undone = Option.unwrap(EditHistory.undo(unchanged));
  expect(undone.present).toEqual(documentOfWidth(375));
});

test("中身の変わらない 1 件目に続きが届いても、1 回戻ればまとまりの前へ戻る", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );
  const unchanged = EditHistory.record(edited, documentOfWidth(414));

  const continued = EditHistory.amend(unchanged, documentOfWidth(768));

  // 中身の変わらない 1 件目を `record` が積まずに弾く実装を落とす（理由は `EditHistory.record` の doc）
  const undone = Option.unwrap(EditHistory.undo(continued));
  expect(undone.present).toEqual(documentOfWidth(414));
});

test("中身の変わらない編集のあとに別の編集を積んでも、2 回戻れば 2 つ前へ戻る", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );
  const unchanged = EditHistory.record(edited, documentOfWidth(414));

  const separated = EditHistory.record(unchanged, documentOfWidth(768));

  const undone = Option.unwrap(EditHistory.undo(separated));
  const twice = Option.unwrap(EditHistory.undo(undone));
  expect([undone.present, twice.present]).toEqual([
    documentOfWidth(414),
    documentOfWidth(375),
  ]);
});

test("開いた直後に中身の変わらない編集を積んでも、戻る先は無い", () => {
  const opened = EditHistory.create(documentOfWidth(375));

  const unchanged = EditHistory.record(opened, documentOfWidth(375));

  expect(Option.isSome(EditHistory.undo(unchanged))).toBe(false);
});

test("続きで元の中身へ戻ったまとまりは、戻すときに飛ばされる", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );
  const started = EditHistory.record(edited, documentOfWidth(768));

  const returned = EditHistory.amend(started, documentOfWidth(414));

  const undone = Option.unwrap(EditHistory.undo(returned));
  expect(undone.present).toEqual(documentOfWidth(375));
});

/*
 * `undo` の入口だけで 1 件落とす実装では落ちる。`record` の入口でも落としていることを守る。
 */
test("中身の変わらない編集を 2 回続けて積んでも、1 回戻れば直前の編集の前へ戻る", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );

  const unchangedTwice = EditHistory.record(
    EditHistory.record(edited, documentOfWidth(414)),
    documentOfWidth(414),
  );

  const undone = Option.unwrap(EditHistory.undo(unchangedTwice));
  expect(undone.present).toEqual(documentOfWidth(375));
});

test("中身の変わらない編集のあと戻してからやり直すと、1 回で戻す前の中身へ進み、それ以上は進めない", () => {
  const edited = EditHistory.record(
    EditHistory.create(documentOfWidth(375)),
    documentOfWidth(414),
  );
  const unchanged = EditHistory.record(edited, documentOfWidth(414));
  const undone = Option.unwrap(EditHistory.undo(unchanged));

  const redone = Option.unwrap(EditHistory.redo(undone));

  expect([redone.present, Option.isSome(EditHistory.redo(redone))]).toEqual([
    documentOfWidth(414),
    false,
  ]);
});

test("別のまとまりとして送った値は 1 回の Undo で直前の値までしか戻らない", () => {
  const edited = sendColors(setupSelected(), [
    { color: "#ff0000", continuity: EditContinuities.Separate },
    { color: "#00ff00", continuity: EditContinuities.Separate },
  ]);

  const undone = Option.unwrap(EditorState.undo(edited));

  expect(primaryOf(undone)).toEqual(Option.some("#ff0000"));
});

test("値を変えずに送った確定は、Undo 1 回で直前に変えた値の前まで戻る", () => {
  const edited = sendColors(setupSelected(), [
    { color: "#ff0000", continuity: EditContinuities.Separate },
    { color: "#ff0000", continuity: EditContinuities.Separate },
  ]);

  const undone = Option.unwrap(EditorState.undo(edited));

  expect(primaryOf(undone)).toEqual(Option.some("#000000"));
});

test("1 打鍵目が値を変えず 2 打鍵目で変わっても、1 回戻れば打ち始める前の値に戻る", () => {
  const first = typeWidths(setupSelected(), [150]);
  const second = typeWidths(first, [150, 120]);

  const undone = Option.unwrap(EditorState.undo(second));

  expect([panelWidth(second), panelWidth(undone)]).toEqual([120, 150]);
});

test("幅を同じ値で確定しても、Undo 1 回で直前の編集の前へ戻る", () => {
  const first = typeWidths(setupSelected(), [150]);
  const unchanged = typeWidths(first, [150]);

  const undone = Option.unwrap(EditorState.undo(unchanged));

  expect(panelWidth(undone)).toBe(200);
});

test("色を変えたあと不透明度の欄を変えずに離れても、Ctrl+Z 1 回でピッカーで選ぶ前の色に戻る", async () => {
  await renderTokensView();
  await selectRow("primary");
  fireEvent.click(field("値"));
  fireEvent.change(field("値"), { target: { value: "#00ff00" } });

  await userEvent.click(field("不透明度"));
  await userEvent.tab();
  blurActive();
  await userEvent.keyboard("{Control>}z{/Control}");

  expect(field("値")).toHaveProperty("value", "#3b82f6");
});

test("色を変えたあと名前の欄を変えずに離れても、Ctrl+Z 1 回でピッカーで選ぶ前の色に戻る", async () => {
  await renderTokensView();
  await selectRow("primary");
  fireEvent.click(field("値"));
  fireEvent.change(field("値"), { target: { value: "#00ff00" } });

  await userEvent.click(field("名前"));
  await userEvent.tab();
  blurActive();
  await userEvent.keyboard("{Control>}z{/Control}");

  expect(field("値")).toHaveProperty("value", "#3b82f6");
});

/**
 * 配列か。`JsonValue` の配列は readonly なので、素の `Array.isArray` では絞れない。
 *
 * @param value 判定する JSON の値
 * @returns 配列なら true
 */
function isJsonArray(value: JsonValue): value is readonly JsonValue[] {
  return Array.isArray(value);
}

function objectEquals(object: JsonObject, other: JsonObject): boolean {
  const keys = Object.keys(object);

  // `other[key]` は自身に無いキーでも prototype の値を返す（`__proto__` なら `Object.prototype`）
  const hasSameValueAt = (key: string): boolean =>
    RecordEx.has(other, key) && Json.equals(object[key], other[key]);

  return (
    keys.length === Object.keys(other).length && keys.every(hasSameValueAt)
  );
}

equals<T>(
  array: readonly T[],
  other: readonly T[],
  equalsElement: (element: T, otherElement: T) => boolean,
): boolean {
  return (
    array.length === other.length &&
    array.every((item, index) => equalsElement(item, other[index]))
  );
},

function withoutUnchangedLast(history: EditHistory): EditHistory {
  const unchanged = Option.equals(
    ArrayEx.last(history.past),
    Option.some(history.present),
    DesignDocument.isSameContent,
  );
  if (!unchanged) {
    return history;
  }
  return { ...history, past: ArrayEx.dropLast(history.past) };
}

/**
 * 2 つのドキュメントが同じ中身か。ファイルに書き出す形（`toJson`）どうしで比べる。
 *
 * 参照ではなく中身を見るのは、編集の関数が中身を変えなくても新しい参照を返すことがあるため。
 *
 * @param document 比べるドキュメント
 * @param other 比べるドキュメント
 * @returns 同じ参照か、`toJson` の結果がキーの並びを除いて等しければ true
 */
isSameContent(document: DesignDocument, other: DesignDocument): boolean {
  if (document === other) {
    return true;
  }
  return Json.equals(
    DesignDocument.toJson(document),
    DesignDocument.toJson(other),
  );
},
